import assert from 'node:assert/strict';
import { createFeed } from './src/tenant-event-feed/index.mjs';
import { createRouter } from './src/layered-routing/index.mjs';
import { ExpiringStore } from './src/tenant-cache/store.mjs';
import { TenantCache } from './src/tenant-cache/cache.mjs';

const feed = createFeed();
let liveA, liveB;
feed.subscribe('a', 0, e => { liveA = e; e.payload.nested.value = 'changed'; });
feed.subscribe('a', 0, e => { liveB = e; });
const source = { nested: { value: 'original' } };
const [published] = feed.publishBatch('a', [{ type: 'x', payload: source }]);
source.nested.value = 'source changed';
assert.equal(liveB.payload.nested.value, 'original');
assert.equal(feed.history('a')[0].payload.nested.value, 'original');
assert.equal(published.payload.nested.value, 'original');
assert.notEqual(liveA, liveB);
assert.throws(() => feed.publishBatch('a', [
  { type: 'ok', payload: {} }, { type: '', payload: {} },
]));
assert.deepEqual(feed.history('a').map(record => record.sequence), [1]);
assert.equal(feed.publishBatch('b', [{ type: 'retry', payload: {} }])[0].sequence, 2);
assert.deepEqual(feed.history('b').map(record => record.sequence), [2]);

const defaults = { enabled: true, timeout: 10, label: 'default', headers: { a: 'a', b: 'b' } };
const routes = [
  { id: 'wild', pattern: '*', settings: { timeout: 2 } },
  { id: 'prefix', pattern: '/app/*', settings: { timeout: 0, headers: { a: null, c: '' } } },
  { id: 'long', pattern: '/app/deep/*', settings: { target: 'deep' } },
  { id: 'exact', pattern: '/app/deep', settings: { label: '' } },
];
const router = createRouter({ defaults, routes });
defaults.enabled = false; routes[1].settings.timeout = 8;
assert.equal(router.resolve('one', '/app/deep').route, 'exact');
const result = router.resolve('one', '/app/deep/x');
assert.equal(result.route, 'long');
assert.equal(result.timeout, 0);
assert.equal(result.enabled, true);
assert.deepEqual(result.headers, { b: 'b', c: '' });
router.setTenant('one', { enabled: false, headers: { b: null } });
assert.equal(router.resolve('one', '/app/deep/x').enabled, false);
assert.deepEqual(router.resolve('one', '/app/deep/x').headers, { c: '' });
assert.equal(router.resolve('two', '/app/deep/x').enabled, true);
router.setTenant('one', { label: 'new' });
assert.equal(router.resolve('one', '/app/deep/x').label, 'new');
assert.equal(router.resolve('app', '/apple'), null);

let now = 100;
const store = new ExpiringStore({ now: () => now });
const cache = new TenantCache(store);
assert.equal(await cache.getOrLoad('a:b', 'c', async () => 0, 5), 0);
assert.equal(await cache.getOrLoad('a', 'b:c', async () => 1, 5), 1);
assert.equal(await cache.getOrLoad('a:b', 'c', async () => 2, 5), 0);
now = 105;
assert.equal(await cache.getOrLoad('a:b', 'c', async () => 3, 5), 3);
console.log('additional contract checks passed');
